<?php /** @var \App\Site\Component\Home $home */ ?>
<h2>Demos</h2><ul id="demos"><?php foreach ($home->demos as $homeDemo): ?><li><?php if ($homeDemo->plain): ?><a class="aic-link" href="<?= $homeDemo->path ?>" data-enhance="off"><?= $homeDemo->label ?></a><?php else: ?><a class="aic-link" href="<?= $homeDemo->path ?>"><?= $homeDemo->label ?></a><?php endif ?></li><?php endforeach ?></ul><h2>This request</h2><p>The AIC kernel is serving this request.</p><dl><?php foreach ($home->facts as $homeFact): ?><dt><?= $homeFact->term ?></dt><dd id="<?= $homeFact->id ?>"><?= $homeFact->value ?></dd><?php endforeach ?></dl><ul id="query"><?php foreach ($home->query as $pair): ?><li><?= $pair ?></li><?php endforeach ?></ul><?= $home->form ?>